values
('20000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','In 3/8, which number is the numerator?','[{"id":"A","text":"3"},{"id":"B","text":"8"},{"id":"C","text":"11"},{"id":"D","text":"0"}]','A',1,'The numerator is the top number, which is 3.'),
('20000000-0000-0000-0000-000000000002','11111111-1111-1111-1111-111111111111','In 5/9, which number is the denominator?','[{"id":"A","text":"5"},{"id":"B","text":"9"},{"id":"C","text":"14"},{"id":"D","text":"1"}]','B',1,'The denominator is the bottom number, 9.'),
('20000000-0000-0000-0000-000000000003','11111111-1111-1111-1111-111111111111','For 7/10, the numerator is...','[{"id":"A","text":"10"},{"id":"B","text":"7"},{"id":"C","text":"17"},{"id":"D","text":"0"}]','B',1,'Top number = numerator, so 7.'),
('20000000-0000-0000-0000-000000000004','11111111-1111-1111-1111-111111111111','For 2/6, the denominator is...','[{"id":"A","text":"2"},{"id":"B","text":"6"},{"id":"C","text":"8"},{"id":"D","text":"4"}]','B',1,'Bottom number = denominator, so 6.'),
('20000000-0000-0000-0000-000000000005','11111111-1111-1111-1111-111111111111','Which part of a fraction tells how many equal parts are chosen?','[{"id":"A","text":"Denominator"},{"id":"B","text":"Numerator"},{"id":"C","text":"Whole number"},{"id":"D","text":"Quotient"}]','B',2,'The numerator shows how many parts are taken.'),
('20000000-0000-0000-0000-000000000006','11111111-1111-1111-1111-111111111111','Which part tells total equal parts in the whole?','[{"id":"A","text":"Numerator"},{"id":"B","text":"Denominator"},{"id":"C","text":"Remainder"},{"id":"D","text":"Product"}]','B',2,'The denominator tells total equal parts.'),
('20000000-0000-0000-0000-000000000007','11111111-1111-1111-1111-111111111111','In 9/12, identify the numerator.','[{"id":"A","text":"12"},{"id":"B","text":"9"},{"id":"C","text":"3"},{"id":"D","text":"21"}]','B',2,'The top number 9 is the numerator.'),
('20000000-0000-0000-0000-000000000008','11111111-1111-1111-1111-111111111111','In 9/12, identify the denominator.','[{"id":"A","text":"12"},{"id":"B","text":"9"},{"id":"C","text":"108"},{"id":"D","text":"1"}]','A',2,'The bottom number 12 is the denominator.'),
('20000000-0000-0000-0000-000000000009','11111111-1111-1111-1111-111111111111','Which statement is true for 4/7?','[{"id":"A","text":"4 is denominator"},{"id":"B","text":"7 is numerator"},{"id":"C","text":"4 is numerator"},{"id":"D","text":"No numerator"}]','C',2,'4 is on top, so it is the numerator.'),
('20000000-0000-0000-0000-000000000010','11111111-1111-1111-1111-111111111111','Which statement is true for 4/7?','[{"id":"A","text":"7 is denominator"},{"id":"B","text":"4 is denominator"},{"id":"C","text":"Both are numerators"},{"id":"D","text":"Neither"}]','A',2,'7 is the bottom number, so denominator.'),
('20000000-0000-0000-0000-000000000011','11111111-1111-1111-1111-111111111111','Sara writes 11/15. What is the denominator?','[{"id":"A","text":"11"},{"id":"B","text":"15"},{"id":"C","text":"26"},{"id":"D","text":"5"}]','B',3,'The denominator is the bottom number, 15.'),
('20000000-0000-0000-0000-000000000012','11111111-1111-1111-1111-111111111111','Leo writes 11/15. What is the numerator?','[{"id":"A","text":"11"},{"id":"B","text":"15"},{"id":"C","text":"4"},{"id":"D","text":"0"}]','A',3,'The numerator is the top number, 11.'),
('20000000-0000-0000-0000-000000000013','11111111-1111-1111-1111-111111111111','Choose the fraction where 6 is the numerator and 13 is denominator.','[{"id":"A","text":"13/6"},{"id":"B","text":"6/13"},{"id":"C","text":"6 + 13"},{"id":"D","text":"13-6"}]','B',3,'Numerator goes on top: 6/13.'),
('20000000-0000-0000-0000-000000000014','11111111-1111-1111-1111-111111111111','Choose the fraction where 14 is denominator and 3 is numerator.','[{"id":"A","text":"14/3"},{"id":"B","text":"3/14"},{"id":"C","text":"17/14"},{"id":"D","text":"14/14"}]','B',3,'Numerator is top (3), denominator is bottom (14).'),
('20000000-0000-0000-0000-000000000015','11111111-1111-1111-1111-111111111111','In fraction 18/25, what does 25 represent?','[{"id":"A","text":"Chosen parts"},{"id":"B","text":"Total equal parts"},{"id":"C","text":"A mixed number"},{"id":"D","text":"No meaning"}]','B',4,'The denominator (25) is total equal parts.'),
('20000000-0000-0000-0000-000000000016','11111111-1111-1111-1111-111111111111','In fraction 18/25, what does 18 represent?','[{"id":"A","text":"Total equal parts"},{"id":"B","text":"Chosen parts"},{"id":"C","text":"Decimal point"},{"id":"D","text":"Denominator"}]','B',4,'The numerator (18) is chosen parts.'),
('20000000-0000-0000-0000-000000000017','11111111-1111-1111-1111-111111111111','A fraction has numerator 1 and denominator 100. Which is it?','[{"id":"A","text":"100/1"},{"id":"B","text":"1/100"},{"id":"C","text":"101/100"},{"id":"D","text":"10/10"}]','B',4,'Top is 1 and bottom is 100, so 1/100.'),
('20000000-0000-0000-0000-000000000018','11111111-1111-1111-1111-111111111111','Which label matches the number on top of a fraction bar?','[{"id":"A","text":"Denominator"},{"id":"B","text":"Numerator"},{"id":"C","text":"Dividend"},{"id":"D","text":"Divisor"}]','B',4,'Top number is always the numerator.'),
('20000000-0000-0000-0000-000000000019','11111111-1111-1111-1111-111111111111','In 27/31, the denominator and numerator are...','[{"id":"A","text":"27 and 31"},{"id":"B","text":"31 and 27"},{"id":"C","text":"Both 31"},{"id":"D","text":"Both 27"}]','B',5,'Denominator is bottom (31), numerator is top (27).'),
('20000000-0000-0000-0000-000000000020','11111111-1111-1111-1111-111111111111','Pick the sentence that is correct.','[{"id":"A","text":"Numerator is always the bottom"},{"id":"B","text":"Denominator is always the top"},{"id":"C","text":"Numerator is top; denominator is bottom"},{"id":"D","text":"Fractions do not have two parts"}]','C',5,'Correct vocabulary: numerator top, denominator bottom.')
